-- NCFTA layer 3: REFINED | prepared locally, not deployed/server-validated.
-- Catalog v2.0.0 SHA-256: 58bf1531ceb3c2957b34ae8ddf8c14c37ec076db2ad2e166878c1fb9c2244cda
-- Exactly 118 catalog columns + 33 technical columns = 151 columns.
-- Row grain: one saved RAW attribute outcome per transformation version.
-- Logical unique key: (RESULT_ID, TRANSFORM_VERSION); enforced by future procedure.
-- A retry reuses its row; a new RAW observation or transform retains its history.
-- This is an observation/history table, not an active-only or person/account table.
-- Arrays contain strings; the transformation must validate element types/spans.
-- Two observation metadata fields preserve source text rather than model output.
-- Deleted/unevaluated rows retain lineage; model field arrays remain SQL NULL.
-- No event values, source files, model files or mapping workbooks are changed.
-- Run as an authorized role, separately from load transactions.
-- IF NOT EXISTS does NOT migrate an earlier table; run the verification script.
-- No rows are loaded and no procedures/views/permissions are created here.
-- Syntax references:
-- https://docs.snowflake.com/en/sql-reference/sql/create-table
-- https://docs.snowflake.com/en/sql-reference/data-types-semistructured

USE DATABASE COMPLIANCE_SCREENING_SANDBOX;

CREATE TABLE IF NOT EXISTS REFINED.NCFTA_FIELDS (
  CURATED_ROW_ID VARCHAR(36) NOT NULL COMMENT 'Stable loader UUID for RESULT_ID and TRANSFORM_VERSION',
  RESULT_ID VARCHAR(36) NOT NULL COMMENT 'Links to RAW.NCFTA_MODEL_RESULTS',
  SOURCE_BATCH_ID VARCHAR(36) NOT NULL COMMENT 'Links to RAW.NCFTA_BATCHES',
  EVENT_SNAPSHOT_ID VARCHAR(36) NOT NULL COMMENT 'Links to RAW.NCFTA_EVENTS',
  SOURCE_INSTANCE_ID VARCHAR NOT NULL COMMENT 'Source namespace from the batch; no credentials',
  EVENT_UUID VARCHAR(36),
  OBJECT_UUID VARCHAR(36),
  ATTRIBUTE_UUID VARCHAR(36),
  SOURCE_EVENT_ID VARCHAR,
  SOURCE_OBJECT_ID VARCHAR,
  SOURCE_ATTRIBUTE_ID VARCHAR,
  SOURCE_REVIEW_ID VARCHAR NOT NULL COMMENT 'Saved internal join key, not a source UUID',
  EVENT_SHARING_GROUP_ID VARCHAR,
  ATTRIBUTE_SHARING_GROUP_ID VARCHAR,
  ATTRIBUTE_DISTRIBUTION VARCHAR,
  SOURCE_TYPE VARCHAR,
  SOURCE_CATEGORY VARCHAR,
  SOURCE_ATTRIBUTE_SHA256 VARCHAR(64) NOT NULL COMMENT 'Source attribute hash copied from RAW',
  MODEL_SHA256 VARCHAR(64) NOT NULL,
  CATALOG_SHA256 VARCHAR(64) NOT NULL,
  PREDICTION_IDENTITY VARCHAR(64) NOT NULL COMMENT 'Saved inference identity; not a source version timestamp',
  TRANSFORM_VERSION VARCHAR NOT NULL,
  OUTCOME_STATUS VARCHAR NOT NULL COMMENT 'predicted, deleted, invalid_source, empty_value or input_error',
  SOURCE_ATTRIBUTE_DELETED BOOLEAN COMMENT 'Original attribute deletion signal; absent stays NULL',
  SOURCE_OBJECT_DELETED BOOLEAN COMMENT 'Original parent object deletion signal; absent stays NULL',
  IS_DELETED BOOLEAN NOT NULL COMMENT 'True when either source signal is true; absence is not a deletion',
  REVIEW_STATUS VARCHAR NOT NULL DEFAULT 'NOT_REVIEWED' COMMENT 'No automatic analyst approval',
  ACCEPTED_SPAN_COUNT NUMBER(38,0) NOT NULL,
  REJECTED_SPAN_COUNT NUMBER(38,0) NOT NULL,
  MULTIVALUE_FIELDS ARRAY NOT NULL COMMENT 'Catalog keys with more than one accepted occurrence',
  WARNINGS ARRAY NOT NULL COMMENT 'Saved extraction and validation warnings',
  CREATED_BY_LOAD_RUN_ID VARCHAR(36) NOT NULL COMMENT 'LOAD_RUN_ID in AUDIT_LAYER.NCFTA_LOAD_AUDIT',
  CURATED_AT TIMESTAMP_TZ NOT NULL DEFAULT CURRENT_TIMESTAMP() COMMENT 'Ingestion time, never source version order',
  REPORTED_ACTOR_NAME ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Source-reported threat actor name; no account ownership inferred.',
  COMPANY_NAME ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Company reported by the source; not automatically a merchant.',
  DATE_OF_BIRTH ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Accepted calendar dates; no automatic association with a particular name.',
  ALIAS_NAME ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Source-reported alias or moniker. Link to a person only when supported.',
  AGE ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Source-reported age, including units. Do not derive without a defined reference date.',
  PLACE_OF_BIRTH ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Source-reported birthplace, distinct from address and residence.',
  OCCUPATION ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Source-reported occupation or job title.',
  EMPLOYER_NAME ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Organization explicitly reported as an employer.',
  SOURCE_COC_LABEL ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Preserve the COC label and value. The abbreviation meaning has not been confirmed.',
  SOURCE_COR_LABEL ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Preserve the COR label and value. The abbreviation meaning has not been confirmed.',
  REGISTERED_AGENT ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Person or organization explicitly identified as a registered agent.',
  ALTERNATE_TRADE_NAME ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Source-reported alternate business or trading name.',
  REPORTED_GENDER ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Gender explicitly reported in the source. Do not infer from a name.',
  ADDRESS ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Source-reported addresses; ownership and address components not inferred.',
  PHONE_NUMBER ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Normalized phone strings; mobile status and country code not inferred.',
  EMAIL_ADDRESS ARRAY COMMENT 'Literal text values in source-span order; [] means evaluated with no accepted match; NULL means not evaluated. Email strings passing the configured basic format check.',
